    {
      "id": "p01",
      "task_equivalent": true,
      "authorization_equivalent": true,
      "information_order_preserved": true,
      "reason": "The request maintains the core action and information, with 'Could you' being a polite rephrasing of 'Can you'."
    },
    {
      "id": "p02",
      "task_equivalent": false,
      "authorization_equivalent": false,
      "information_order_preserved": true,
      "reason": "The phrase 'Is it possible to check' asks about the ability or possibility, rather than directly requesting the action. It shifts from a direct request to an inquiry about capability."
    },
    {
      "id": "p03",
      "task_equivalent": true,
      "authorization_equivalent": true,
      "information_order_preserved": true,
      "reason": "Adding 'please' enhances politeness but does not alter the core request or its authorization."
    },
    {
      "id": "p04",
      "task_equivalent": true,
      "authorization_equivalent": true,
      "information_order_preserved": true,
      "reason": "'Please help me check' is a polite way to request the same action, implying the user needs assistance with the checking."
    },
    {
      "id": "p05",
      "task_equivalent": true,
      "authorization_equivalent": true,
      "information_order_preserved": true,
      "reason": "Rephrasing to an imperative with 'please' at the end maintains the request for the action."
    },
    {
      "id": "n01",
      "task_equivalent": true,
      "authorization_equivalent": true,
      "information_order_preserved": true,
      "reason": "This is identical to the source request, thus fully equivalent."
    },
    {
      "id": "n02",
      "task_equivalent": false,
      "authorization_equivalent": false,
      "information_order_preserved": true,
      "reason": "'Are you able to check' questions the capability rather than directly requesting the action, similar to p02."
    },
    {
      "id": "n03",
      "task_equivalent": true,
      "authorization_equivalent": true,
      "information_order_preserved": true,
      "reason": "'Can you help me check' is a neutral way to request assistance with the checking, maintaining the core task."
    },
    {
      "id": "n04",
      "task_equivalent": true,
      "authorization_equivalent": true,
      "information_order_preserved": true,
      "reason": "An imperative with 'please' is a direct request for the action."
    },
    {
      "id": "n05",
      "task_equivalent": true,
      "authorization_equivalent": true,
      "information_order_preserved": true,
      "reason": "A direct imperative 'Check what happened' is a clear request for the action."
    },
    {
      "id": "i01",
      "task_equivalent": true,
      "authorization_equivalent": true,
      "information_order_preserved": true,
      "reason": "'Just check' is an impolite imperative, but it still requests the same action."
    },
    {
      "id": "i02",
      "task_equivalent": true,
      "authorization_equivalent": true,
      "information_order_preserved": true,
      "reason": "The imperative 'Check what happened at the front door' is followed by 'Do it', which reinforces the command without changing the core task."
    },
    {
      "id": "i03",
      "task_equivalent": true,
      "authorization_equivalent": true,
      "information_order_preserved": true,
      "reason": "'This time, check' implies a previous interaction or failure, but the core request to check remains the same."
    },
    {
      "id": "i04",
      "task_equivalent": true,
      "authorization_equivalent": true,
      "information_order_preserved": true,
      "reason": "'You need to check' is a strong directive that conveys the same task as a request."
    },
    {
      "id": "i05",
      "task_equivalent": false,
      "authorization_equivalent": false,
      "information_order_preserved": true,
      "reason": "'Why can't you check' is a rhetorical question that challenges the recipient's ability or willingness, rather than making a direct request to perform the action. It implies a previous conversation or expectation."
    }
  ]
}
